/** Verify the shipped public origin, not Next's private upstream. Every
 * declared brand asset (manifest + shortcut icons, Apple touch icon and
 * startup images, favicons) must be served with the right MIME type and,
 * for PNGs, the declared pixel dimensions. The assets are committed
 * (generated by `scripts/build-icons.mjs`), so a miss is a hard failure. */
const origin = process.env.PLAYWRIGHT_BASE_URL ?? process.argv[2];
if (!origin)
  throw new Error("Set PLAYWRIGHT_BASE_URL or pass the public origin");
const failures = [];
let checked = 0;
async function get(path, type) {
  const response = await fetch(new URL(path, origin));
  checked++;
  if (!response.ok || !response.headers.get("content-type")?.includes(type)) {
    failures.push(
      `${path}: ${response.status} ${response.headers.get("content-type")}`,
    );
    return null;
  }
  return response;
}
/** Fetch a PNG and compare its IHDR width/height with `[width, height]`. */
async function png(path, expected) {
  const response = await get(path, "image/png");
  if (!response) return;
  const bytes = new DataView(await response.arrayBuffer());
  if (
    bytes.byteLength < 24 ||
    bytes.getUint32(0) !== 0x89504e47 ||
    (expected &&
      (bytes.getUint32(16) !== expected[0] ||
        bytes.getUint32(20) !== expected[1]))
  )
    failures.push(`${path}: invalid PNG or dimensions (want ${expected})`);
}
const sizes = (s) => s?.split(" ")[0].split("x").map(Number);

const manifestResponse = await get("/manifest.webmanifest", "json");
if (manifestResponse) {
  const manifest = await manifestResponse.json();
  if (manifest.id !== "/" || manifest.scope !== "/")
    failures.push("Unexpected manifest identity/scope");
  if (manifest.display !== "standalone")
    failures.push(`Manifest display is ${manifest.display}`);
  const purposes = new Set((manifest.icons ?? []).map((i) => i.purpose));
  if (!purposes.has("any") || !purposes.has("maskable"))
    failures.push("Manifest needs both `any` and `maskable` icons");
  const icons = [
    ...(manifest.icons ?? []),
    ...(manifest.shortcuts ?? []).flatMap((shortcut) => {
      if (!shortcut.icons?.length)
        failures.push(`Shortcut ${shortcut.name} has no icon`);
      return shortcut.icons ?? [];
    }),
  ];
  for (const icon of icons)
    if (icon.type === "image/png") await png(icon.src, sizes(icon.sizes));
    else await get(icon.src, icon.type);
}
const html = await (await get("/sign-in", "text/html"))?.text();
const links = html?.match(/<link\b[^>]*>/g) ?? [];
let appleIcons = 0;
for (const tag of links) {
  const rel = tag.match(/rel="([^"]+)"/)?.[1];
  const path = tag.match(/href="([^"]+)"/)?.[1];
  if (!path) continue;
  if (rel === "apple-touch-icon") {
    appleIcons++;
    await png(path, [180, 180]);
  } else if (rel === "apple-touch-startup-image") {
    const media = tag.match(/media="([^"]+)"/)?.[1] ?? "";
    const [, w, h, r, orientation] =
      media.match(
        /device-width: (\d+)px\) and \(device-height: (\d+)px\) and \(-webkit-device-pixel-ratio: (\d+)\) and \(orientation: (\w+)\)/,
      ) ?? [];
    const px = [w * r, h * r];
    await png(
      path,
      w ? (orientation === "portrait" ? px : px.reverse()) : null,
    );
  } else if (rel === "icon") {
    await get(path, path.endsWith(".svg") ? "image/svg+xml" : "image/");
  }
}
if (!appleIcons) failures.push("No apple-touch-icon link in the document");
if (!/name="apple-mobile-web-app-capable" content="yes"/.test(html ?? ""))
  failures.push("Missing apple-mobile-web-app-capable meta");
const worker = await get("/sw.js", "javascript");
if (
  worker &&
  !/no-cache|no-store|max-age=0/.test(worker.headers.get("cache-control") ?? "")
)
  failures.push("Worker must revalidate");
await get("/offline.html", "text/html");
await get("/favicon.ico", "image/");
if (failures.length) throw new Error(failures.join("\n"));
console.warn(`PWA origin checks passed (${checked} requests)`);
